def amdahl(p, cores):               # p is the fraction of the work that runs in parallel
    return 1 / ((1 - p) + p / cores)

print([round(amdahl(0.95, n), 2) for n in (8, 64, 1024)])   # [5.93, 15.42, 19.64]

