def has_dup_naive(xs):                # O(n^2): compares every pair
    for i in range(len(xs)):
        for j in range(i + 1, len(xs)):
            if xs[i] == xs[j]: return True
    return False

def has_dup_set(xs):                  # O(n): a set remembers what it has seen
    return len(set(xs)) != len(xs)

def quicksort(xs):
    if len(xs) <= 1: return xs
    pivot, rest = xs[0], xs[1:]
    return quicksort([x for x in rest if x < pivot]) + [pivot] + quicksort([x for x in rest if x >= pivot])

print(quicksort([42, 7, 19, 3, 88, 23]))   # [3, 7, 19, 23, 42, 88]

static int find(const int *a, int n, int key) {
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;   /* not (lo + hi) / 2, which can overflow */
        if (a[mid] == key) return mid;
        if (a[mid] < key) lo = mid + 1; else hi = mid - 1;
    }
    return -1;                          /* not found */
}

def edit_distance(a, b):
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        cur = [i]
        for j, cb in enumerate(b, 1):
            cur.append(min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (ca != cb)))
        prev = cur
    return prev[-1]

print(edit_distance("kitten", "sitting"))   # 3

